#include <Wire.h>
#include <LiquidCrystal_I2C.h>

// Адрес 0x27 — самый частый. Если не заработает, попробуй 0x3F
LiquidCrystal_I2C lcd(0x27, 16, 2);

void setup() {
  lcd.init();              // Инициализация экрана
  lcd.backlight();         // Включаем подсветку в начале
  lcd.print("Hello!");     // Можно написать любой текст — он будет виден, когда подсветка горит
}

void loop() {
  lcd.noBacklight();       // Выключаем подсветку
  delay(500);              // Пауза 0.5 секунды
  lcd.backlight();         // Включаем подсветку
  delay(500);              // Пауза 0.5 секунды
}
